insert into public.entities (id, entity_type, slug, name, scientific_name, summary, simple_summary, tags, review_status, updated_at) values ('7ec2aa2a-232c-5eae-9bc9-f11c69b1c0be', 'plant', 'curcuma', '{"es":"Cúrcuma","en":"Turmeric"}'::jsonb, 'Curcuma longa L.', '{"es":"Especia obtenida del rizoma de Curcuma longa. Su compuesto más estudiado es la curcumina. Ha sido objeto de numerosos estudios, pero hay poca evidencia clínica sólida para usos específicos en salud.","en":"Spice obtained from the rhizome of Curcuma longa. Its most studied compound is curcumin. It has been studied extensively, but there is little reliable clinical evidence for specific health uses."}'::jsonb, '{"es":"La cúrcuma es la especia amarilla del curry. Se ha investigado mucho, pero todavía no está demostrado que sirva para tratar enfermedades concretas.","en":"Turmeric is the yellow spice in curry. It has been researched a lot, but it has not been shown to treat specific diseases."}'::jsonb, array['especia', 'antiinflamatorio-investigado', 'cancer-investigado']::text[], 'pending_review', '2026-10-03');
insert into public.plants (entity_id, family, synonyms, botanical_description, distribution, legal_notes, name_ambiguity) values ('7ec2aa2a-232c-5eae-9bc9-f11c69b1c0be', 'Zingiberaceae', '{}'::text[], null, '{"es":"Cultivada en regiones tropicales; asociada históricamente al sur de Asia.","en":"Cultivated in tropical regions; historically associated with South Asia."}'::jsonb, null, null);
