insert into public.entities (id, entity_type, slug, name, scientific_name, summary, simple_summary, tags, review_status, updated_at) values ('6dee24ed-ce53-52a8-ae9e-ec7cb6bd2cd9', 'food', 'brocoli', '{"es":"Brócoli","en":"Broccoli"}'::jsonb, 'Brassica oleracea var. italica Plenck', '{"es":"Verdura crucífera rica en glucosinolatos (como la glucorafanina), precursores del sulforafano. Los estudios sobre crucíferas y cáncer muestran resultados no concluyentes.","en":"Cruciferous vegetable rich in glucosinolates (such as glucoraphanin), precursors of sulforaphane. Studies on cruciferous vegetables and cancer are inconclusive."}'::jsonb, '{"es":"El brócoli contiene sustancias que los científicos estudian en relación con el cáncer. Comer verduras es parte de una dieta saludable, pero no se ha demostrado que el brócoli por sí solo prevenga el cáncer.","en":"Broccoli contains substances scientists study in relation to cancer. Eating vegetables is part of a healthy diet, but broccoli alone has not been shown to prevent cancer."}'::jsonb, array['cancer-investigado', 'prevencion']::text[], 'pending_review', '2026-10-03');
