insert into public.evidence_claims (id, subject_id, condition_id, context, level, category, study_types, human_evidence, statement, simple, what_we_know, what_we_dont_know, under_investigation, risks, limitations, research_doses, review_status, updated_at) values ('7d427496-5f89-5e99-b7de-66b3f286e191', '88f8fd3f-4483-5a00-9911-863afdc1c719', '7698d1f1-1ee3-5b79-9b39-54094609aab0', 'research', 'E', 'preclinical', array['in_vitro', 'animal']::study_type[], false, '{"es":"La curcumina se ha estudiado ampliamente en cultivos celulares y modelos animales de cáncer colorrectal. Estos resultados experimentales no demuestran eficacia en personas.","en":"Curcumin has been studied extensively in cell cultures and animal models of colorectal cancer. These experimental results do not demonstrate efficacy in people."}'::jsonb, '{"es":"La curcumina es una sustancia presente en la cúrcuma. Los científicos la han estudiado en diferentes tipos de cáncer, pero los resultados obtenidos en laboratorio no significan automáticamente que consumir cúrcuma pueda tratar un cáncer en una persona.","en":"Curcumin is a substance found in turmeric. Scientists have studied it in different types of cancer, but laboratory results do not automatically mean that eating turmeric can treat cancer in a person."}'::jsonb, '[{"es":"Existe una gran cantidad de estudios de laboratorio y en animales.","en":"There is a large body of laboratory and animal studies."},{"es":"Hay poca evidencia clínica fiable sobre la cúrcuma para cualquier condición.","en":"There is little reliable clinical evidence on turmeric for any condition."}]'::jsonb, '[{"es":"Si la curcumina mejora algún resultado clínico en personas con cáncer colorrectal.","en":"Whether curcumin improves any clinical outcome in people with colorectal cancer."},{"es":"Qué dosis o formulación serían relevantes y seguras en este contexto.","en":"Which dose or formulation would be relevant and safe in this context."}]'::jsonb, '[{"es":"Pueden existir ensayos clínicos registrados; consúltelos en el modo Investigación (ClinicalTrials.gov).","en":"Registered clinical trials may exist; check them in Research mode (ClinicalTrials.gov)."}]'::jsonb, '[{"es":"Casos notificados de daño hepático con suplementos.","en":"Reported cases of liver injury with supplements."}]'::jsonb, '[{"es":"Los efectos en células y animales con frecuencia no se reproducen en humanos.","en":"Effects in cells and animals often do not replicate in humans."}]'::jsonb, null, 'pending_review', '2026-10-03');
