insert into public.evidence_claims (id, subject_id, condition_id, context, level, category, study_types, human_evidence, statement, simple, what_we_know, what_we_dont_know, under_investigation, risks, limitations, research_doses, review_status, updated_at) values ('99f2a5b2-56be-5847-8aa4-5e91fc7e044f', '6dee24ed-ce53-52a8-ae9e-ec7cb6bd2cd9', 'ca59b075-1917-59ca-9d91-4ac3cd642244', 'prevention', 'D', 'observational', array['cohort', 'case_control', 'in_vitro', 'animal']::study_type[], true, '{"es":"Los estudios en animales han sugerido efectos protectores de compuestos de las crucíferas, pero los estudios en humanos sobre el consumo de crucíferas y el riesgo de cáncer han mostrado resultados inconsistentes.","en":"Animal studies have suggested protective effects of compounds in cruciferous vegetables, but human studies on cruciferous vegetable intake and cancer risk have shown inconsistent results."}'::jsonb, '{"es":"Comer brócoli y otras crucíferas forma parte de una dieta saludable, pero no está demostrado que por sí solas prevengan el cáncer.","en":"Eating broccoli and other cruciferous vegetables is part of a healthy diet, but they have not been shown to prevent cancer on their own."}'::jsonb, '[{"es":"Los datos observacionales muestran asociaciones, no causalidad.","en":"Observational data show associations, not causation."}]'::jsonb, '[{"es":"Si el efecto observado se debe a las crucíferas o a otros hábitos asociados.","en":"Whether the observed effect is due to the vegetables or other associated habits."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"es":"Factor asociado ≠ causa demostrada.","en":"Associated factor ≠ proven cause."}]'::jsonb, null, 'pending_review', '2026-10-03');
