insert into public.evidence_claims (id, subject_id, condition_id, context, level, category, study_types, human_evidence, statement, simple, what_we_know, what_we_dont_know, under_investigation, risks, limitations, research_doses, review_status, updated_at) values ('71e2d984-759f-5bf8-9cff-a2f154d03640', '785f4bc0-2cbb-5908-8e8f-7b6e84f05607', '7698d1f1-1ee3-5b79-9b39-54094609aab0', 'prevention', 'D', 'observational', array['cohort', 'case_control', 'regulatory_evaluation']::study_type[], true, '{"es":"La IARC (OMS) clasificó la carne procesada como carcinógena para humanos (Grupo 1), con base en evidencia epidemiológica suficiente de su relación con el cáncer colorrectal. La carne roja se clasificó como probablemente carcinógena (Grupo 2A).","en":"IARC (WHO) classified processed meat as carcinogenic to humans (Group 1), based on sufficient epidemiological evidence linking it to colorectal cancer. Red meat was classified as probably carcinogenic (Group 2A)."}'::jsonb, '{"es":"Comer carne procesada (embutidos, salchichas) con frecuencia se relaciona con más riesgo de cáncer de colon. Reducir su consumo es una medida de prevención.","en":"Eating processed meat (cold cuts, sausages) often is linked to higher colon cancer risk. Eating less of it is a prevention measure."}'::jsonb, '[{"es":"La clasificación del Grupo 1 indica la solidez de la evidencia de que causa cáncer, no la magnitud del riesgo.","en":"Group 1 reflects the strength of evidence that it causes cancer, not the size of the risk."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, 'pending_review', '2026-10-03');
