insert into public.evidence_claims (id, subject_id, condition_id, context, level, category, study_types, human_evidence, statement, simple, what_we_know, what_we_dont_know, under_investigation, risks, limitations, research_doses, review_status, updated_at) values ('a8c51853-e03e-5063-9647-8da61eceb859', '50398504-9863-5219-9bd1-e1e99986f194', '94d6a37b-b83e-5bf4-b4fd-11d50eac5e65', 'complementary', 'A', 'clinical_strong', array['rct', 'regulatory_evaluation']::study_type[], true, '{"es":"Medicamentos a base de cannabinoides (dronabinol, un THC sintético, y nabilona) están aprobados por la FDA para náuseas y vómitos asociados a la quimioterapia cuando otros tratamientos no han funcionado. Esto se refiere a medicamentos regulados, no a la planta de cannabis.","en":"Cannabinoid-based medicines (dronabinol, a synthetic THC, and nabilone) are FDA-approved for chemotherapy-associated nausea and vomiting when other treatments have not worked. This refers to regulated medicines, not the cannabis plant."}'::jsonb, '{"es":"Algunos medicamentos hechos con sustancias parecidas a las del cannabis ayudan con las náuseas de la quimioterapia. Los receta el médico; no es lo mismo que usar la planta.","en":"Some medicines made with cannabis-like substances help with chemotherapy nausea. They are prescribed by a doctor; this is not the same as using the plant."}'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"es":"Efectos psicoactivos, mareo, somnolencia.","en":"Psychoactive effects, dizziness, drowsiness."}]'::jsonb, '[]'::jsonb, null, 'pending_review', '2026-10-03');
