insert into public.evidence_claims (id, subject_id, condition_id, context, level, category, study_types, human_evidence, statement, simple, what_we_know, what_we_dont_know, under_investigation, risks, limitations, research_doses, review_status, updated_at) values ('5c882dbf-edca-5700-828a-7b399fd9fd85', 'c0d2c144-203a-5dd1-93eb-b18ba097236a', 'ca59b075-1917-59ca-9d91-4ac3cd642244', 'complementary', 'B', 'clinical_limited', array['rct']::study_type[], true, '{"es":"El PSK se ha evaluado en ensayos clínicos, principalmente en Japón, como complemento de la quimioterapia en algunos tipos de cáncer (por ejemplo, gástrico y colorrectal). Los resultados proceden de poblaciones y protocolos específicos y no se generalizan automáticamente.","en":"PSK has been evaluated in clinical trials, mainly in Japan, as an adjunct to chemotherapy in some cancers (for example, gastric and colorectal). Results come from specific populations and protocols and do not automatically generalize."}'::jsonb, '{"es":"Una sustancia de un hongo (cola de pavo) se ha probado en Japón junto con la quimioterapia. No sustituye el tratamiento y su uso debe hablarse con el oncólogo.","en":"A substance from a mushroom (turkey tail) has been tested in Japan alongside chemotherapy. It does not replace treatment and must be discussed with the oncologist."}'::jsonb, '[{"es":"Ningún resultado de laboratorio o en animales justifica sustituir, retrasar o abandonar un tratamiento oncológico.","en":"No laboratory or animal result justifies replacing, delaying or abandoning cancer treatment."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"es":"El PSK es un producto farmacéutico estandarizado; comer o tomar el hongo no es equivalente.","en":"PSK is a standardized pharmaceutical product; eating or taking the mushroom is not equivalent."}]'::jsonb, null, 'pending_review', '2026-10-03');
