insert into public.evidence_claims (id, subject_id, condition_id, context, level, category, study_types, human_evidence, statement, simple, what_we_know, what_we_dont_know, under_investigation, risks, limitations, research_doses, review_status, updated_at) values ('5869d100-d237-504c-9ad8-d191e72d4975', 'ca3d9003-8fae-54f3-a163-f417474e076d', 'ca59b075-1917-59ca-9d91-4ac3cd642244', 'research', 'C', 'preliminary', array['in_vitro', 'animal', 'rct']::study_type[], true, '{"es":"La investigación del reishi en cáncer es mayoritariamente preclínica; los pocos estudios en humanos son pequeños y de calidad limitada.","en":"Reishi cancer research is mostly preclinical; the few human studies are small and of limited quality."}'::jsonb, '{"es":"El reishi se estudia en el laboratorio; no se ha demostrado que trate el cáncer.","en":"Reishi is studied in the lab; it has not been shown to treat cancer."}'::jsonb, '[{"es":"Ningún resultado de laboratorio o en animales justifica sustituir, retrasar o abandonar un tratamiento oncológico.","en":"No laboratory or animal result justifies replacing, delaying or abandoning cancer treatment."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, 'pending_review', '2026-10-03');
